from pathlib import Path
import json
V={
'v_assessment_due':"SELECT e.id,e.name,e.community_id,a.id assessment_id,a.valid_until FROM elder e JOIN assessment a ON a.elder_id=e.id WHERE a.valid_until BETWEEN NOW() AND NOW()+INTERVAL 30 DAY",
'v_active_plan':"SELECT p.id,p.elder_id,e.name,e.community_id,p.starts_at,p.ends_at,c.name caregiver_name FROM v_plan_context p JOIN elder e ON e.id=p.elder_id JOIN caregiver c ON c.id=p.caregiver_id WHERE p.status='ACTIVE' AND NOW()>=p.starts_at AND NOW()<p.ends_at",
'v_family_care':"SELECT g.account_id,e.id elder_id,e.name,e.community_id,p.id plan_id,p.status FROM guardian g JOIN elder e ON e.id=g.elder_id LEFT JOIN v_plan_context p ON p.elder_id=e.id AND p.status='ACTIVE'",
'v_dispatch_overdue':"SELECT o.id,o.elder_id,o.community_id,o.starts_at,o.status FROM service_order o WHERE o.status='PENDING' AND o.created_at<NOW()-INTERVAL 15 MINUTE",
'v_wait_confirmation':"SELECT o.id,o.elder_id,o.community_id,r.id record_id FROM service_order o JOIN v_dispatch_context d ON d.order_id=o.id JOIN service_record r ON r.dispatch_id=d.id WHERE o.status='CONFIRM' AND r.confirmed_at IS NULL",
'v_reassign_history':"SELECT d.id,d.order_id,d.caregiver_id,c.name,d.reason,d.assigned_at,o.community_id FROM v_dispatch_context d JOIN caregiver c ON c.id=d.caregiver_id JOIN service_order o ON o.id=d.order_id WHERE d.status='REASSIGNED'",
'v_credential_due':"SELECT x.id,c.name,c.organization_id,x.item_id,x.valid_until FROM credential x JOIN caregiver c ON c.id=x.caregiver_id WHERE x.valid_until<NOW()+INTERVAL 30 DAY",
'v_shift_capacity':"SELECT s.id,s.caregiver_id,c.organization_id,s.starts_at,s.ends_at,s.capacity-s.used_count available FROM shift s JOIN caregiver c ON c.id=s.caregiver_id WHERE s.status='OPEN'",
'v_hours_review':"SELECT a.id,d.caregiver_id,c.organization_id,d.order_id,a.check_in,a.check_out,a.location_note,a.status FROM attendance a JOIN v_dispatch_context d ON d.id=a.dispatch_id JOIN caregiver c ON c.id=d.caregiver_id WHERE a.status='REVIEW'",
'v_device_current':"SELECT d.id,d.serial_no,d.status,b.elder_id,e.community_id,b.bound_at FROM device d LEFT JOIN device_binding b ON b.device_id=d.id AND b.unbound_at IS NULL LEFT JOIN elder e ON e.id=b.elder_id",
'v_abnormal_vital':"SELECT v.id,b.elder_id,e.community_id,m.metric,v.metric_value,v.collected_at FROM vital v JOIN device_binding b ON b.id=v.binding_id JOIN elder e ON e.id=b.elder_id JOIN metric_rule m ON m.id=v.metric_rule_id WHERE v.abnormal=1",
'v_emergency_pending':"SELECT x.id,x.elder_id,e.community_id,x.status,x.level,x.deadline,TIMESTAMPDIFF(SECOND,NOW(),x.deadline) remaining_seconds FROM emergency x JOIN elder e ON e.id=x.elder_id WHERE x.status NOT IN('CLOSED','FALSE_ALARM')",
'v_claim_eligible':"SELECT o.id,o.elder_id,o.item_id,o.community_id,o.amount,a.effective_minutes FROM service_order o JOIN v_dispatch_context d ON d.order_id=o.id JOIN attendance a ON a.dispatch_id=d.id JOIN service_record r ON r.dispatch_id=d.id JOIN service_item s ON s.id=o.item_id WHERE o.status='COMPLETED' AND d.status='FINISHED' AND r.confirmed_at IS NOT NULL AND a.status='VALID' AND s.subsidizable=1 AND NOT EXISTS(SELECT 1 FROM claim_item ci WHERE ci.order_id=o.id)",
'v_claim_progress':"SELECT c.id,c.elder_id,e.community_id,c.period,c.amount,c.status,p.reference_no,p.paid_at FROM claim c JOIN elder e ON e.id=c.elder_id LEFT JOIN payment p ON p.claim_id=c.id",
'v_rectification':"SELECT i.id,i.order_id,i.caregiver_id,i.issue,i.rectification,a.community_id FROM inspection i JOIN account a ON a.id=i.inspector_id WHERE i.status='OPEN'"}
Path('database/03_views.sql').write_text('\n'.join(f'CREATE VIEW {k} AS {v};' for k,v in V.items())+'\n')
# Each pair returns the same columns; distinct is deliberate for existential queries.
Q=[]
def add(code,title,a,b,explain):Q.append(dict(id=code,title=title,a=a,b=b,comparison=explain))
add('A1','有效评估与计划的重度失能老人',"SELECT DISTINCT e.id,e.name FROM elder e JOIN assessment a ON a.elder_id=e.id JOIN v_plan_context p ON p.assessment_id=a.id WHERE a.ability_level='SEVERE' AND p.status='ACTIVE' AND a.valid_until>NOW()","SELECT e.id,e.name FROM elder e WHERE EXISTS(SELECT 1 FROM assessment a JOIN v_plan_context p ON p.assessment_id=a.id WHERE a.elder_id=e.id AND a.ability_level='SEVERE' AND p.status='ACTIVE' AND a.valid_until>NOW())",'连接去重与 EXISTS 半连接比较，避免一人多记录重复输出。')
add('A2','每个老人的评估次数',"SELECT e.id,COUNT(a.id) n FROM elder e LEFT JOIN assessment a ON a.elder_id=e.id GROUP BY e.id","SELECT e.id,(SELECT COUNT(*) FROM assessment a WHERE a.elder_id=e.id) n FROM elder e",'左连接聚合与相关子查询；保留零次评估老人。')
add('A3','没有生效计划的老人',"SELECT e.id FROM elder e LEFT JOIN v_plan_context p ON p.elder_id=e.id AND p.status='ACTIVE' WHERE p.id IS NULL","SELECT e.id FROM elder e WHERE NOT EXISTS(SELECT 1 FROM v_plan_context p WHERE p.elder_id=e.id AND p.status='ACTIVE')",'反连接与 NOT EXISTS，不使用含 NULL 风险的 NOT IN。')
add('B1','有改派历史的订单',"SELECT DISTINCT o.id,e.name FROM service_order o JOIN elder e ON e.id=o.elder_id JOIN v_dispatch_context d ON d.order_id=o.id WHERE d.status='REASSIGNED'","SELECT o.id,e.name FROM service_order o JOIN elder e ON e.id=o.elder_id WHERE EXISTS(SELECT 1 FROM v_dispatch_context d WHERE d.order_id=o.id AND d.status='REASSIGNED')",'多表连接去重与 EXISTS，结果粒度为订单。')
add('B2','各社区订单金额',"SELECT c.id,COALESCE(SUM(o.amount),0) total FROM community c LEFT JOIN service_order o ON o.community_id=c.id GROUP BY c.id","SELECT c.id,COALESCE((SELECT SUM(o.amount) FROM service_order o WHERE o.community_id=c.id),0) total FROM community c",'聚合与相关子查询，空集合显式转零。')
add('B3','待确认订单',"SELECT DISTINCT o.id FROM service_order o JOIN v_dispatch_context d ON d.order_id=o.id JOIN service_record r ON r.dispatch_id=d.id WHERE o.status='CONFIRM' AND r.confirmed_at IS NULL","SELECT o.id FROM service_order o WHERE o.status='CONFIRM' AND EXISTS(SELECT 1 FROM v_dispatch_context d JOIN service_record r ON r.dispatch_id=d.id WHERE d.order_id=o.id AND r.confirmed_at IS NULL)",'保留订单粒度，防止多次派单重复统计。')
add('C1','护工有效工时',"SELECT c.id,COALESCE(SUM(a.effective_minutes),0) minutes FROM caregiver c LEFT JOIN v_dispatch_context d ON d.caregiver_id=c.id LEFT JOIN attendance a ON a.dispatch_id=d.id AND a.status='VALID' GROUP BY c.id","SELECT c.id,COALESCE((SELECT SUM(a.effective_minutes) FROM v_dispatch_context d JOIN attendance a ON a.dispatch_id=d.id WHERE d.caregiver_id=c.id AND a.status='VALID'),0) minutes FROM caregiver c",'三表聚合与子查询。未服务护工仍返回零。')
add('C2','有空余名额的护工',"SELECT DISTINCT c.id FROM caregiver c JOIN shift s ON s.caregiver_id=c.id WHERE s.status='OPEN' AND s.used_count<s.capacity","SELECT c.id FROM caregiver c WHERE EXISTS(SELECT 1 FROM shift s WHERE s.caregiver_id=c.id AND s.status='OPEN' AND s.used_count<s.capacity)",'该查询只检查容量，不等同于完整派单资格推荐。')
add('C3','证书到期护工',"SELECT DISTINCT c.id FROM caregiver c JOIN credential x ON x.caregiver_id=c.id WHERE x.valid_until<NOW()","SELECT c.id FROM caregiver c WHERE EXISTS(SELECT 1 FROM credential x WHERE x.caregiver_id=c.id AND x.valid_until<NOW())",'到期清单与完整资质判断分离，一张证书到期不代表所有项目失效。')
add('D1','老人异常体征数量',"SELECT e.id,COUNT(v.id) n FROM elder e LEFT JOIN device_binding b ON b.elder_id=e.id LEFT JOIN vital v ON v.binding_id=b.id AND v.abnormal=1 GROUP BY e.id","SELECT e.id,(SELECT COUNT(*) FROM device_binding b JOIN vital v ON v.binding_id=b.id WHERE b.elder_id=e.id AND v.abnormal=1) n FROM elder e",'绑定历史关联，不能仅通过设备当前归属统计。')
add('D2','存在未关闭事件的老人',"SELECT DISTINCT e.id FROM elder e JOIN emergency x ON x.elder_id=e.id WHERE x.status NOT IN('CLOSED','FALSE_ALARM')","SELECT e.id FROM elder e WHERE EXISTS(SELECT 1 FROM emergency x WHERE x.elder_id=e.id AND x.status NOT IN('CLOSED','FALSE_ALARM'))",'连接去重与 EXISTS，待确认事件仍纳入。')
add('D3','当前未绑定设备',"SELECT d.id FROM device d LEFT JOIN device_binding b ON b.device_id=d.id AND b.unbound_at IS NULL WHERE b.id IS NULL","SELECT d.id FROM device d WHERE NOT EXISTS(SELECT 1 FROM device_binding b WHERE b.device_id=d.id AND b.unbound_at IS NULL)",'历史绑定不应排除当前空闲设备。')
add('E1','按社区汇总已申报金额',"SELECT co.id,COALESCE(SUM(c.amount),0) amount FROM community co LEFT JOIN elder e ON e.community_id=co.id LEFT JOIN claim c ON c.elder_id=e.id AND c.status<>'DRAFT' GROUP BY co.id","SELECT co.id,COALESCE((SELECT SUM(c.amount) FROM elder e JOIN claim c ON c.elder_id=e.id WHERE e.community_id=co.id AND c.status<>'DRAFT'),0) amount FROM community co",'当前管理辖区统计口径；历史财政归属应改按政策辖区统计。')
add('E2','待拨付申报',"SELECT c.id FROM claim c LEFT JOIN payment p ON p.claim_id=c.id WHERE c.status='APPROVED' AND p.id IS NULL","SELECT c.id FROM claim c WHERE c.status='APPROVED' AND NOT EXISTS(SELECT 1 FROM payment p WHERE p.claim_id=c.id)",'反连接与 NOT EXISTS。')
add('E3','各申报明细合计',"SELECT c.id,COALESCE(SUM(i.amount),0) amount FROM claim c LEFT JOIN claim_item i ON i.claim_id=c.id GROUP BY c.id","SELECT c.id,COALESCE((SELECT SUM(i.amount) FROM claim_item i WHERE i.claim_id=c.id),0) amount FROM claim c",'汇总后与主表金额比较，用于核算一致性检查。')
Path('database/queries.json').write_text(json.dumps(Q,ensure_ascii=False,indent=2))
Path('database/04_queries.sql').write_text('\n\n'.join(f"-- {q['id']} {q['title']}\n-- {q['comparison']}\n-- 实现 A\n{q['a']};\n-- 实现 B\n{q['b']};" for q in Q))
